class Solution:
    def smallestDistancePair(self, nums: list[int], k: int) -> int:
        nums.sort()
        n = len(nums)

        def enough(distance) -> bool:
            count, i = 0, 0
            for j in range(n):
                while nums[j] - nums[i] > distance:
                    i += 1
                count += j - i
            return count >= k

        left, right = 0, nums[-1] - nums[0]
        while left < right:
            mid = left + (right - left) // 2
            if enough(mid):
                right = mid
            else:
                left = mid + 1
        return left

